var F_=.003352810681182319,DEG=Math.PI/180,n=F_/(2-F_),n2=n*n,n3=n2*n,n4=n3*n,AR=6378137/(1+n)*(1+n2/4+n4/64),alpha=[n/2-2/3*n2+5/16*n3+41/180*n4,13/48*n2-3/5*n3+557/1440*n4,61/240*n3-103/140*n4,49561/161280*n4],beta=[n/2-2/3*n2+37/96*n3-1/360*n4,1/48*n2+1/15*n3-437/1440*n4,17/480*n3-37/840*n4,4397/161280*n4],delta=[2*n-2/3*n2-2*n3+116/45*n4,7/3*n2-8/5*n3-227/45*n4,56/15*n3-136/35*n4,4279/630*n4],e2n=2*Math.sqrt(n)/(1+n);function makeTM(lon0Deg,k0=.9996,FE=5e5,FN=0){let lon0=lon0Deg*DEG;function forward(lonDeg,latDeg){let phi=latDeg*DEG,lam=lonDeg*DEG-lon0,sp=Math.sin(phi),t=Math.sinh(Math.atanh(sp)-e2n*Math.atanh(e2n*sp)),xi=Math.atan2(t,Math.cos(lam)),eta=Math.atanh(Math.sin(lam)/Math.sqrt(1+t*t)),E=eta,N=xi;for(let j=1;j<=4;j++)E+=alpha[j-1]*Math.cos(2*j*xi)*Math.sinh(2*j*eta),N+=alpha[j-1]*Math.sin(2*j*xi)*Math.cosh(2*j*eta);return[FE+k0*AR*E,FN+k0*AR*N]}function inverse(E,N){let xi=(N-FN)/(k0*AR),eta=(E-FE)/(k0*AR),xp=xi,ep=eta;for(let j=1;j<=4;j++)xp-=beta[j-1]*Math.sin(2*j*xi)*Math.cosh(2*j*eta),ep-=beta[j-1]*Math.cos(2*j*xi)*Math.sinh(2*j*eta);let chi=Math.asin(Math.sin(xp)/Math.cosh(ep)),phi=chi;for(let j=1;j<=4;j++)phi+=delta[j-1]*Math.sin(2*j*chi);let lam=Math.atan2(Math.sinh(ep),Math.cos(xp));return[(lon0+lam)/DEG,phi/DEG]}function trueNorthGrid(lonDeg,latDeg){let[x0,y0]=forward(lonDeg,latDeg),[x1,y1]=forward(lonDeg,latDeg+.001);return Math.atan2(x1-x0,y1-y0)/DEG}return{forward,inverse,trueNorthGrid,lon0:lon0Deg}}var UTM33=makeTM(15),UTM32=makeTM(9);function fmtLat(lat){let h=lat>=0?"N":"S";lat=Math.abs(lat);let d=Math.floor(lat),m=(lat-d)*60;return`${d}\xB0${m.toFixed(3).padStart(6,"0").replace(".",",")}\u2032${h}`}function fmtLon(lon){let h=lon>=0?"\xD8":"V";lon=Math.abs(lon);let d=Math.floor(lon),m=(lon-d)*60;return`${String(d).padStart(3,"0")}\xB0${m.toFixed(3).padStart(6,"0").replace(".",",")}\u2032${h}`}export{UTM33,fmtLat,fmtLon};
